SELECT 'missing_gene_coordinates' AS problem,COUNT(*) AS records FROM genes WHERE chromosome IS NULL OR start_position IS NULL OR end_position IS NULL UNION ALL SELECT 'missing_trait_class',COUNT(*) FROM traits WHERE metabolite_class IS NULL UNION ALL SELECT 'missing_go_metadata',COUNT(*) FROM go_terms WHERE go_name IS NULL OR ontology IS NULL UNION ALL SELECT 'duplicate_trait_genes',COUNT(*) FROM (SELECT trait_id,gene_id FROM trait_genes GROUP BY trait_id,gene_id HAVING COUNT(*)>1) UNION ALL SELECT 'duplicate_gene_go',COUNT(*) FROM (SELECT gene_id,go_id FROM gene_go GROUP BY gene_id,go_id HAVING COUNT(*)>1) UNION ALL SELECT 'foreign_key_violations',COUNT(*) FROM pragma_foreign_key_check UNION ALL SELECT 'duplicate_source_candidates',COUNT(*) FROM (SELECT trait_id,gene_id FROM candidate_records GROUP BY trait_id,gene_id HAVING COUNT(*)>1);
